function fill(t, vars) { return t.replace(/\{(\w+)\}/g, (m, k) => (vars[k] ?? m)); }
function buildOpenAI(model, system, userObj, maxTokens) {
  const req = {
    model,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: typeof userObj === 'string' ? userObj : JSON.stringify(userObj) }
    ],
    response_format: { type: 'json_object' },
    max_completion_tokens: maxTokens || 1500
  };
  // GPT-5 family / o-series are reasoning models: keep reasoning light for chat latency
  if (/^(gpt-5|o\d)/.test(model)) req.reasoning_effort = 'low';
  return req;
}
const CONV = "You are the customer communication assistant for {company}. You write {channel} messages to homeowners.\n\nRules:\n1. Be concise: at most 2 short sentences plus one question. No emojis unless the customer uses them.\n2. Be professional and friendly ({brand_voice}).\n3. Never invent prices, discounts, or deadlines. If asked about price, say a specialist gives a written quote after the free inspection.\n4. Never invent appointment availability and never write specific dates or times \u2014 the system appends real open times itself.\n5. Never claim an appointment is booked, confirmed, or scheduled.\n6. Never provide unsafe instructions (no climbing on roofs, no electrical advice). For active leaks you may suggest moving valuables and placing a bucket.\n7. Do not diagnose structural problems.\n8. Do not pretend to be human. If asked, say you're the {company} virtual assistant and a team member can help anytime.\n9. Ask only for information needed to move the conversation forward \u2014 one question at a time.\n10. Only use facts from the company info JSON.\n11. Never ask for anything listed in already_known_do_not_ask_again (for example the property address from the web form).\n\nCompany info JSON is provided with each request.\nReturn JSON only: {\"reply\": \"message text\", \"next_action\": \"WAIT_FOR_CUSTOMER\"|\"HUMAN\"|\"NONE\"}";
const MODES = {"FIRST_CONTACT": "The lead just submitted a form. Thank them by first name if known, reference their problem briefly, and ask the single most useful next question (usually: is it an active leak / when would an inspection work).", "ANSWER": "Answer the customer's latest question using only company info, then gently move toward a free inspection.", "QUALIFY": "Ask for the most important missing detail. Missing fields (most important first): {missing}.", "OFFER_SLOTS": "Write ONE short sentence introducing available free inspection times. Do NOT list or mention any dates or times \u2014 the system appends the exact options below your sentence.", "NO_SLOTS": "There are no open inspection times in the requested window. Apologise briefly and say a team member will reach out to schedule. Do not mention times.", "DISQUALIFIED": "Politely explain we can't help with this request (reason: {reason}) and thank them. No question needed.", "FOLLOWUP": "Write a gentle, no-pressure follow-up to a lead who went quiet (follow-up #{step}). Reference their roofing issue if known and offer a free inspection. Keep it under 240 characters.", "NO_SHOW": "The customer missed their free roof inspection. Say kindly that we're sorry we missed them, that it's no problem, and introduce new free inspection times in ONE short sentence. Do NOT list or mention any dates or times: the system appends the exact options below your sentence.", "REENGAGE": "We haven't heard from this customer in over a month. Write a friendly, no-pressure check-in about their roofing issue (if known) and offer a free inspection. No urgency, no deadlines. Keep it under 240 characters.", "POST_CALL": "The customer just finished a phone call with our voice assistant. Send a brief recap of the next step ({reason}). Do not mention times."};

const t = $('EXECUTE_WORKFLOW_TRIGGER').first().json;
const ctx = $('GET_LEAD').first().json;
const org = $('GET_COMPANY_RULES').first().json;
const s = org.settings || {};
const lead = ctx.lead;
const mode = t.mode || 'ANSWER';
const channel = t.channel === 'whatsapp' ? 'WhatsApp' : 'SMS';
const system = fill(CONV, { company: org.name, channel, brand_voice: s.ai?.brand_voice || 'friendly, professional' });
// never ask again for what we already know (e.g. the address from the web form)
const known = {};
if (lead.name) known.name = lead.name;
if (lead.address) known.address = lead.address;
if (lead.problem_type) known.problem_type = lead.problem_type;
if (lead.email) known.email = lead.email;
const missing = (t.missing_fields || []).filter(f => !(
  (f === 'address' && lead.address) || (f === 'name' && lead.name) || (f === 'problem_type' && lead.problem_type)));
const instruction = fill(MODES[mode] || MODES.ANSWER, {
  missing: missing.join(', ') || (lead.address ? 'urgency and how soon they need help' : 'problem details and property address'),
  reason: t.router_reason || 'n/a', step: t.step || 1
});
const user = {
  task: instruction,
  mode,
  company_info: { name: org.name, services: s.services, service_area: s.service_area?.description, faq: s.faq || {} },
  customer: { first_name: (lead.name || '').split(' ')[0] || null, problem_type: lead.problem_type, urgency: lead.urgency, status: lead.status },
  already_known_do_not_ask_again: known,
  conversation: $('GET_MESSAGES').first().json.history || [],
  latest_customer_message: t.body || t.inbound_text || null
};
const model = (['FOLLOWUP','REENGAGE'].includes(mode) ? s.ai?.models?.followup : s.ai?.models?.conversation) || 'gpt-5.4';
return [{ json: { openai_request: buildOpenAI(model, system, user, 1200) } }];

const r = $json;
const content = r.choices?.[0]?.message?.content || '';
let parsed = null, parse_error = null;
try { parsed = JSON.parse(content); }
catch (e) {
  const m = content.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parse_error = e2.message; } }
  else parse_error = e.message || 'empty response';
}
return [{ json: {
  parsed, parse_error, raw: content,
  model: r.model || null,
  prompt_tokens: r.usage?.prompt_tokens ?? null,
  completion_tokens: r.usage?.completion_tokens ?? null
}}];

const t = $('EXECUTE_WORKFLOW_TRIGGER').first().json;
const p = $('PARSE_JSON').first().json;
const org = $('GET_COMPANY_RULES').first().json;
const s = org.settings || {};
const lead = $('GET_LEAD').first().json.lead;
const mode = t.mode || 'ANSWER';
const first = (lead.name || '').split(' ')[0];
const hi = first ? `Hi ${first}` : 'Hi';
const o = p.parsed || {};
let reply = typeof o.reply === 'string' ? o.reply.trim() : '';
const errors = [];
if (!p.parsed) errors.push('unparseable: ' + p.parse_error);
if (!reply) errors.push('empty reply');
const faqText = JSON.stringify(s.faq || {});
if (/\$\s?\d|\b\d[\d,]*\s?(dollars|usd)\b/i.test(reply) && !/\$\s?\d/.test(faqText)) errors.push('mentions a price');
if (/\b(you('| a)?re (all )?(set|booked|scheduled|confirmed) for|appointment (is |has been )?(booked|confirmed|scheduled))\b/i.test(reply)) errors.push('claims a booking');
if (/\b(climb|get|go) (up )?(on|onto) (the|your) roof\b/i.test(reply)) errors.push('unsafe instruction');
if (/\b(i am|i'm) (a )?(human|real person)\b/i.test(reply)) errors.push('claims to be human');
const SLOT_MODES = ['OFFER_SLOTS','NO_SHOW'];
if (SLOT_MODES.includes(mode) && /\b\d{1,2}(:\d{2})?\s?(am|pm)\b|\b(mon|tues|wednes|thurs|fri|satur|sun)day\b|\btomorrow\b/i.test(reply)) errors.push('mentions times itself');
if (reply.length > 600) errors.push('too long');
const valid = errors.length === 0;

const FALLBACK = {
  FIRST_CONTACT: `${hi}, thanks for contacting ${org.name}! Is water coming in right now, or is this a non-urgent issue?`,
  ANSWER: `Thanks for your message! A ${org.name} team member will follow up shortly.`,
  QUALIFY: `Thanks! Could you share a little more about the roof issue and the property address?`,
  OFFER_SLOTS: `Here are our next available free inspection times:`,
  NO_SLOTS: `Thanks! Our inspection calendar is full for that window — a team member will reach out to find a time.`,
  DISQUALIFIED: `Thanks for reaching out to ${org.name}. Unfortunately we're not able to help with this request.`,
  FOLLOWUP: `${hi}, just checking in from ${org.name} — would a free roof inspection help? Reply anytime.`,
  POST_CALL: `Thanks for calling ${org.name}! Reply to this text anytime if you have questions.`,
  NO_SHOW: `${hi}, sorry we missed you for your roof inspection, no problem at all. Here are the next free times:`,
  REENGAGE: `${hi}, it's ${org.name} checking in. Is your roof still giving you trouble? We're happy to do a free inspection whenever suits you.`
};
let body = valid ? reply : (FALLBACK[mode] || FALLBACK.ANSWER);

// availability is appended by the system — the model can never invent a time
const slots = (t.slots || []).slice(0, s.max_slots_offered || 3);
if (SLOT_MODES.includes(mode)) {
  body = slots.length
    ? body + '\n' + slots.map((x, i) => `${i + 1}) ${x.label}`).join('\n') + '\nReply with the number that works best.'
    : FALLBACK.NO_SLOTS;
}
if (['FIRST_CONTACT','REENGAGE'].includes(mode) && !/\bSTOP\b/.test(body)) body += ' Reply STOP to opt out.';
return [{ json: { reply: body, ai_reply: reply, valid, errors, mode, used_fallback: !valid,
                  next_action: o.next_action || 'WAIT_FOR_CUSTOMER' } }];

const t = $('EXECUTE_WORKFLOW_TRIGGER').first().json;
const v = $('VALIDATE_RESPONSE').first().json;
return [{ json: {
  lead_id: t.lead_id,
  channel: t.channel === 'whatsapp' ? 'whatsapp' : 'sms',
  body: v.reply,
  ai_generated: !v.used_fallback,
  kind: 'AI_' + v.mode,
  metadata: { mode: v.mode, used_fallback: v.used_fallback, errors: v.errors }
}}];
